import fs from 'node:fs';import assert from 'node:assert/strict';import {spawn} from 'node:child_process';import {hash,json} from './seal-simple-website-successor.mjs';
const stage='F:/VisibleMedicine/staging/20261024-guided-review-current-proof',prep=json(stage+'/PREPARATION.json'),site=prep.website,parent=json(prep.parentReceipt),dir=stage+'/checks';assert(!fs.existsSync(dir));fs.mkdirSync(dir);
const added=['tests/guided-review-completeness.mjs','tests/guided-review-completeness-765.test.mjs','tests/guided-review-completeness-role.test.mjs','tests/fixtures/guided-review-completeness-5f3.mjs.raw'];
const rows=[...parent.sourceRows.map(r=>{assert.equal(hash(site+'/'+r.path),r.sha256,r.path);return r;}),...added.map(p=>({path:p,bytes:fs.statSync(site+'/'+p).size,sha256:hash(site+'/'+p)}))].sort((a,b)=>a.path.localeCompare(b.path));
const write=(p,v)=>fs.writeFileSync(p,JSON.stringify(v,null,2)+'\n',{flag:'wx'});write(stage+'/INPUTS.json',rows);const fingerprint=hash(stage+'/INPUTS.json');
const pointer=json('CURRENT_CHECKPOINT.json');assert.equal(pointer.activeWork.current.activeExecutionSessions.length,0);assert.equal(pointer.activeWork.current.ownerPreviewPolicy.restartPermitted,false);
const args=['--max-old-space-size=768','--experimental-strip-types','--test','--test-concurrency=1','--test-reporter=tap','tests/guided-review-completeness-765.test.mjs','tests/guided-review-completeness-role.test.mjs'];
const out=fs.createWriteStream(dir+'/stdout.log',{flags:'wx'}),err=fs.createWriteStream(dir+'/stderr.log',{flags:'wx'}),startedAt=new Date().toISOString();
const child=spawn(process.execPath,args,{cwd:site,env:{...process.env,NODE_OPTIONS:'--max-old-space-size=768',RAYON_NUM_THREADS:'1',GOMAXPROCS:'2',VM_ATLAS_SOURCE_REPO:prep.atlas,GIT_NO_REPLACE_OBJECTS:'1'},stdio:['ignore','pipe','pipe'],windowsHide:true});child.stdout.pipe(out);child.stderr.pipe(err);write(dir+'/STARTED.json',{startedAt,pid:child.pid,driverPid:process.pid,args,cwd:site,sourceInputsSha256:fingerprint});
function state(active){const p=json('CURRENT_CHECKPOINT.json');p.activeWork.current.activeExecutionSessions=p.activeWork.current.activeExecutionSessions.filter(r=>r.role!=='guided-review-current-proof');if(active)p.activeWork.current.activeExecutionSessions.push({role:'guided-review-current-proof',pid:child.pid,driverPid:process.pid,evidence:dir,previewChanged:false});const text=JSON.stringify(p,null,2)+'\n';assert(Buffer.byteLength(text)<65536);fs.writeFileSync('CURRENT_CHECKPOINT.json',text);}state(true);console.log(JSON.stringify({pid:child.pid,sourcePaths:rows.length,previewChanged:false}));
const result=await new Promise(resolve=>{child.once('error',e=>resolve({code:null,error:e.message}));child.once('close',(code,signal)=>resolve({code,signal}));});await Promise.all([out,err].map(stream=>new Promise(resolve=>stream.closed?resolve():stream.once('close',resolve))));
for(const row of rows)assert.equal(hash(site+'/'+row.path),row.sha256,row.path+': entire input unchanged during execution');assert.equal(hash(stage+'/INPUTS.json'),fingerprint);
const stdout=fs.readFileSync(dir+'/stdout.log','utf8'),counts=Object.fromEntries(['tests','pass','fail','skipped','cancelled'].map(k=>[k,Number(stdout.match(new RegExp('^# '+k+' (\\d+)$','m'))?.[1]??-1)]));
write(dir+'/TERMINAL.json',{startedAt,...result,finishedAt:new Date().toISOString(),pid:child.pid,counts,sourcePaths:rows.length,sourceInputsSha256:fingerprint,entireSourceClosureUnchanged:true,stdoutSha256:hash(dir+'/stdout.log'),stderrSha256:hash(dir+'/stderr.log'),previewChanged:false});state(false);console.log(JSON.stringify({...result,counts,sourcePaths:rows.length,sourceInputsSha256:fingerprint}));process.exitCode=result.code===0?0:1;
